export const WORD_COUNTS: Record<number, number> = {
  1: 150, 2: 150, 3: 100, 4: 60, 5: 50, 6: 50,
};

export function getWordsByLevel(level: number): VocabWord[] {
  return hskVocabulary.filter((w) => w.level === level);
}

export function getWordById(id: string): VocabWord | undefined {
  return hskVocabulary.find((w) => w.id === id);
}

export function searchWords(query: string): VocabWord[] {
  const q = query.toLowerCase();
  return hskVocabulary.filter(
    (w) =>
      w.simplified.includes(q) ||
      w.pinyin.toLowerCase().includes(q) ||
      w.meaning.toLowerCase().includes(q)
  );
}
